CREATE TABLE `inventory_abc_xyz` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `abc_class` enum('A','B','C') NOT NULL DEFAULT 'C',
  `xyz_class` enum('X','Y','Z') NOT NULL DEFAULT 'Z',
  `matrix_quadrant` varchar(4) NOT NULL DEFAULT 'CZ',
  `total_sales_qty` int(11) NOT NULL DEFAULT 0,
  `total_sales_value` decimal(12,2) NOT NULL DEFAULT 0.00,
  `cumulative_share_pct` decimal(6,2) NOT NULL DEFAULT 0.00,
  `cv_score` decimal(8,4) NOT NULL DEFAULT 0.0000,
  `daily_velocity` decimal(10,2) NOT NULL DEFAULT 0.00,
  `days_of_supply` decimal(10,1) NOT NULL DEFAULT 999.0,
  `stockout_probability` decimal(5,2) NOT NULL DEFAULT 0.00,
  `runout_days` int(11) NOT NULL DEFAULT 999,
  `strategy_recommendation` varchar(255) NOT NULL DEFAULT '',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_product` (`product_id`),
  KEY `idx_matrix` (`matrix_quadrant`),
  KEY `idx_abc` (`abc_class`),
  KEY `idx_xyz` (`xyz_class`),
  CONSTRAINT `fk_abc_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=829 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
