DROP TABLE IF EXISTS `inventory_capital_lockup`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `inventory_capital_lockup` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `days_inactive` int(11) NOT NULL DEFAULT 0,
  `idle_stock_qty` int(11) NOT NULL DEFAULT 0,
  `locked_capital_value` decimal(12,2) NOT NULL DEFAULT 0.00,
  `dead_stock_tier` enum('Active','Slow','Dormant_30','Dead_60','Critical_90') NOT NULL DEFAULT 'Active',
  `action_plan` varchar(255) NOT NULL DEFAULT '',
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_lockup_product` (`product_id`),
  KEY `idx_tier` (`dead_stock_tier`),
  CONSTRAINT `fk_lockup_product` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=829 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
